{"id_": "481ed8eb-4078-47b3-9658-11cccb69e4dd", "embedding": null, "metadata": {"pubmed_id": "21402341", "question": "Assessment of carotid artery stenosis before coronary artery bypass surgery. Is it always necessary?", "final_decision": "no"}, "excluded_embed_metadata_keys": [], "excluded_llm_metadata_keys": [], "relationships": {}, "metadata_template": "{key}: {value}", "metadata_separator": "
