{"id_": "6722cce8-d07e-4047-9a9e-39b420c3f7c6", "embedding": null, "metadata": {"pubmed_id": "26134053", "question": "Outcome Feedback within Emergency Medicine Training Programs: An Opportunity to Apply the Theory of Deliberate Practice?", "final_decision": "maybe"}, "excluded_embed_metadata_keys": [], "excluded_llm_metadata_keys": [], "relationships": {}, "metadata_template": "{key}: {value}", "metadata_separator": "
